from ext import *
ext('c12_hin_ch15',[
C("🪔","भक्तिकाल की पृष्ठभूमि",["समय: चौदहवीं से सत्रहवीं सदी","निर्गुण और सगुण धाराएँ","कृष्ण भक्ति शाखा","जनभाषा में कविता"],"सूरदास को समझने के लिए भक्तिकाल को जानना ज़रूरी है। यह हिंदी साहित्य का वह युग है जब कवियों ने ईश्वर के प्रति प्रेम और श्रद्धा को जनता की भाषा में गाया। इसकी दो प्रमुख धाराएँ हैं, निर्गुण, जिसमें कबीर जैसे संत आते हैं, और सगुण, जिसमें राम भक्ति के तुलसीदास और कृष्ण भक्ति के सूरदास हैं। इस काल में कविता दरबार से निकलकर आम लोगों के बीच पहुँची। सूरदास की कृष्ण भक्ति शाखा में कृष्ण के बाल रूप और उनकी लीलाओं का विशेष वर्णन मिलता है।"),
C("🎶","सूरदास का जीवन",["जन्म लगभग 1478 के आसपास","वल्लभाचार्य के शिष्य","अष्टछाप के प्रमुख कवि","ब्रज क्षेत्र में निवास"],"सूरदास का जन्म लगभग पंद्रहवीं सदी के उत्तरार्ध में माना जाता है। वे वल्लभाचार्य के शिष्य बने और अष्टछाप के आठ कवियों में सबसे प्रमुख माने गए। यह माना जाता है कि वे नेत्रहीन थे, फिर भी उनके पदों में रंग, रूप और दृश्यों का ऐसा सजीव वर्णन है कि पढ़ने वाला दंग रह जाता है। उनकी प्रसिद्ध रचनाएँ सूरसागर, सूरसारावली और साहित्य लहरी हैं। सूरसागर में कृष्ण के जन्म से लेकर उनकी बाल लीलाओं और गोपियों के प्रेम तक का भावपूर्ण वर्णन मिलता है।"),
C("🌅","पहला पद: प्रभात का दृश्य",["यशोदा का बच्चे को जगाना","कमल खिले, पक्षी चहचहाए","ग्वाल-बाल द्वार पर","माँ का स्नेह और अनुनय"],"पहले पद में सुबह का मनोहर दृश्य है। माता यशोदा अपने लाड़ले कृष्ण को प्रेम से जगा रही हैं। वे कहती हैं कि देखो, सुबह हो गई, कमल के फूल खिल गए, पक्षी चहचहा रहे हैं और तुम्हारे ग्वाल सखा द्वार पर खड़े इंतज़ार कर रहे हैं। यहाँ माँ का अपार स्नेह और बच्चे को जगाने का कोमल तरीक़ा दिखता है। हर घर में माँ ऐसे ही जगाती है। यही सहजता इस पद को इतना सुंदर बनाती है। इसमें प्रभात की प्रकृति और घर का वातावरण साथ-साथ चित्रित हैं।"),
C("🍚","दूसरा पद: भोजन का दृश्य",["नंद बाबा कृष्ण को खिलाते हैं","कृष्ण थोड़ा खाकर शरारत करते हैं","बाल हठ और माता-पिता का दुलार","स्वाभाविक घरेलू चित्र"],"दूसरे पद में भोजन का सुंदर दृश्य है। नंद बाबा कृष्ण को अपने पास बैठाकर प्रेम से भोजन करा रहे हैं। कृष्ण थोड़ा खाते हैं और थोड़ा इधर-उधर बिखेरते हैं, जैसे हर छोटा बच्चा करता है। माता यशोदा यह सब देखकर प्रसन्न होती हैं। इस पद में बच्चों की स्वाभाविक शरारतों और माता-पिता के दुलार का अत्यंत सुंदर चित्र है। यहाँ कृष्ण भगवान से ज़्यादा एक नटखट बालक लगते हैं, और यही सूरदास की बड़ी विशेषता है कि उन्होंने भगवान को भी घर का बच्चा बना दिया।"),
C("❤️","वात्सल्य रस की व्याख्या",["वात्सल्य: बच्चों के प्रति माता-पिता का स्नेह","स्थायी भाव: संतान विषयक रति","आलंबन: बाल कृष्ण","सूरदास को वात्सल्य का सम्राट कहा जाता है"],"इन पदों का मुख्य रस वात्सल्य है। रस का मतलब है काव्य पढ़ने से मिलने वाला आनंद। वात्सल्य रस में माता-पिता का अपनी संतान के प्रति प्रेम व्यक्त होता है। इसका स्थायी भाव संतान विषयक रति है और आलंबन बाल कृष्ण हैं। उद्दीपन में उनकी शरारतें, तुतलाती बोली और चंचल चेष्टाएँ आती हैं। सूरदास को हिंदी साहित्य में वात्सल्य रस का सम्राट माना जाता है, क्योंकि उनके जैसा बाल मन का चित्रण किसी और कवि ने नहीं किया। परीक्षा में रस का नाम, स्थायी भाव और उदाहरण पूछा जाता है।"),
C("🗣️","ब्रजभाषा की मिठास",["ब्रज क्षेत्र की भाषा","कोमल और मधुर शब्द","तद्भव शब्दों की प्रधानता","गेयता और लय"],"सूरदास ने अपने पद ब्रजभाषा में लिखे। ब्रजभाषा मथुरा-वृंदावन क्षेत्र की मधुर और कोमल भाषा है। इसमें कठोर ध्वनियाँ कम और कोमल ध्वनियाँ अधिक हैं, इसलिए कविता गाने में बहुत सुंदर लगती है। सूर के पद राग-रागिनियों में बाँधे गए थे, इसीलिए उन्हें पद कहा जाता है और वे आज भी भजन की तरह गाए जाते हैं। भाषा सरल है, जिससे साधारण व्यक्ति भी इसे समझ सकता है। अगर आप ब्रजभाषा में रुचि लें, तो सूर के पदों से शुरुआत करना बहुत अच्छा रहेगा।"),
C("🎨","अलंकार और बिंब",["अनुप्रास: वर्णों की आवृत्ति","उपमा और रूपक","दृश्य और श्रव्य बिंब","स्वभावोक्ति: जैसा है वैसा वर्णन"],"सूर के पदों में अलंकारों का सहज प्रयोग है। अनुप्रास यानी एक ही वर्ण का बार-बार आना, जो गेयता बढ़ाता है। उपमा और रूपक भी कई जगह हैं। पर सबसे ख़ास है स्वभावोक्ति, यानी किसी चीज़ का जैसा स्वाभाविक रूप है, वैसा ही वर्णन करना। सूर ने बच्चों के हाव-भाव, हँसी, रोना और ज़िद को बिना बनावट के चित्रित किया है। साथ ही सुबह के खिले कमल, चहकते पक्षियों और गोकुल के वातावरण के जो बिंब हैं, वे आँखों के सामने तस्वीर खड़ी कर देते हैं।"),
C("🏡","माता-पिता और बच्चों का रिश्ता",["माँ की ममता और धैर्य","पिता का स्नेह","बच्चों की ज़िद और शरारत","आज के परिवार की झलक"],"ये पद हमें आज के अपने परिवारों की भी याद दिलाते हैं। हर सुबह माँ का बच्चे को जगाना, पिता का प्यार से खाना खिलाना, बच्चे का ज़िद करना, सब कुछ आज भी वैसा ही है, जैसा पाँच सौ साल पहले था। यही सार्वभौमिकता इन पदों को अमर बनाती है। विद्यार्थी के रूप में हमें अपने माता-पिता के त्याग और स्नेह को महसूस करना चाहिए। जब आप अपने घर की सुबह की व्यस्तता को इन पदों की रोशनी में देखेंगे, तो कविता और भी गहरी लगेगी।"),
C("📘","प्रसंग सहित व्याख्या कैसे लिखें",["प्रसंग: कवि, ग्रंथ, पद का संदर्भ","व्याख्या: पंक्ति दर पंक्ति भाव","विशेष: रस, अलंकार, भाषा","अंत में सार"],"हिंदी में पद की व्याख्या के प्रश्न का एक ढाँचा है। पहले प्रसंग लिखिए, जिसमें कवि का नाम, ग्रंथ या रचना और पद किस प्रसंग का है, यह बताइए। फिर व्याख्या लिखिए, जिसमें पंक्तियों का भाव सरल भाषा में समझाइए। अंत में विशेष लिखिए, जिसमें रस, अलंकार, भाषा और शैली के बिंदु हों, जैसे वात्सल्य रस, ब्रजभाषा और स्वभावोक्ति। हर अनुच्छेद साफ़ अलग रखिए, ताकि जाँचने वाला आसानी से अंक दे सके। इसका अभ्यास घर पर एक पद से ज़रूर कीजिए।"),
C("🕉️","अष्टछाप और पुष्टिमार्ग",["अष्टछाप: आठ कवियों का समूह","वल्लभाचार्य का पुष्टिमार्ग","कृष्ण का बाल स्वरूप","कीर्तन परंपरा"],"सूरदास अष्टछाप के सदस्य थे। अष्टछाप का अर्थ है आठ कवियों का समूह, जिनमें सूरदास, कुंभनदास, परमानंददास और कृष्णदास जैसे कवि हैं। ये सब वल्लभाचार्य और उनके पुत्र विट्ठलनाथ से जुड़े थे। वल्लभाचार्य का पुष्टिमार्ग भक्ति का वह रास्ता है जिसमें ईश्वर की कृपा को मुख्य माना जाता है, और कृष्ण के बाल रूप की पूजा होती है। मंदिरों में सूर के पद कीर्तन के रूप में गाए जाते थे। इस तरह कविता और भक्ति का सुंदर मेल बना और यह परंपरा आज भी जीवित है।"),
C("📝","शब्द और अर्थ",["भोर: सुबह","ग्वाल-बाल: चरवाहे बच्चे","पद: गेय काव्य रूप","लीला: ईश्वर की क्रीड़ा"],"आइए इन पदों के कुछ शब्द और उनके अर्थ याद करें। भोर का अर्थ है सुबह। ग्वाल-बाल यानी गाय चराने वाले ग्वाले और उनके बच्चे, कृष्ण के सखा। पद एक गेय काव्य रूप है, जिसे राग में गाया जाता है। लीला का अर्थ है ईश्वर की क्रीड़ा या खेल। नंद बाबा, यानी कृष्ण के पालक पिता, और यशोदा मैया, यानी पालक माता। इन शब्दों के अर्थ पूरे वाक्य में लिखने का अभ्यास कीजिए। इससे अर्थ भी पक्का होगा और लिखने की क्षमता भी बढ़ेगी।"),
C("🌱","सूर और आज का समाज",["बाल मन को समझना","बच्चों से स्नेह और धैर्य","भक्ति और कला का मेल","गीतों से संस्कार"],"सूरदास की कविताएँ आज भी प्रासंगिक हैं। वे हमें बाल मन को समझना सिखाती हैं, कि बच्चों की शरारत को डाँट से नहीं, स्नेह से सँभालना चाहिए। वे यह भी दिखाती हैं कि गीत और संगीत के माध्यम से संस्कार कितनी सहजता से दिए जा सकते हैं। बिहार में भी माँ के लोरी गाने और सोहर गाने की परंपरा है, जो इसी वात्सल्य भाव से जुड़ती है। अगर आपके घर में दादी-नानी लोरी या सोहर जानती हों, तो उनसे सुनिए और लिख लीजिए।"),
C("📌","पाठ का सार",["सूरदास: कृष्ण भक्ति के कवि","पहला पद: प्रभात का दृश्य","दूसरा पद: भोजन का दृश्य","वात्सल्य रस, ब्रजभाषा"],"अब पाठ का सार दोहरा लें। सूरदास कृष्ण भक्ति शाखा के प्रमुख कवि हैं। पहले पद में यशोदा प्रभात में कृष्ण को जगाती हैं और दूसरे पद में नंद बाबा उन्हें भोजन कराते हैं। दोनों पदों में बाल लीला और माता-पिता के स्नेह का स्वाभाविक चित्रण है। मुख्य रस वात्सल्य है, भाषा ब्रज है और अलंकार सहज हैं। इसे अपने शब्दों में लिखकर अभ्यास कीजिए।"),
C("❓","संभावित परीक्षा प्रश्न",["सूरदास का परिचय","वात्सल्य रस क्या है","पहले पद का भाव","ब्रजभाषा की विशेषताएँ"],"परीक्षा के प्रश्न देखिए। पहला, सूरदास का संक्षिप्त परिचय दीजिए। उत्तर में समय, गुरु, अष्टछाप और रचनाएँ लिखिए। दूसरा, वात्सल्य रस क्या है? उत्तर, माता-पिता का संतान के प्रति स्नेह, उदाहरण कृष्ण की बाल लीलाएँ। तीसरा, पहले पद का भाव, यानी यशोदा का प्रभात में कृष्ण को जगाना। चौथा, ब्रजभाषा की विशेषताएँ, कोमलता, मधुरता और गेयता। हर उत्तर पूरे वाक्य और बिंदुओं में लिखिए।"),
Q("आपके अनुसार सूरदास को वात्सल्य रस का सम्राट क्यों कहा जाता है?","क्योंकि उन्होंने बाल मन और माता-पिता के स्नेह का इतना स्वाभाविक और विस्तृत चित्रण किया कि वैसा कोई और नहीं कर सका।","एक सोचने वाला प्रश्न। सूरदास को वात्सल्य रस का सम्राट क्यों कहा जाता है? सोचिए। ... क्योंकि उन्होंने बाल मन की चंचलता और माता-पिता के स्नेह का इतना स्वाभाविक और विस्तृत चित्रण किया कि वैसा कोई और नहीं कर सका। इसे अपने शब्दों में कॉपी में लिखिए।"),
],7)
